local byID={};for _,e in ipairs(D.entries)do byID[e.id]=e end
local function unique(t,v)for _,x in ipairs(t)do if x==v then return end end;t[#t+1]=v end
-- Some existing canonical figures are materialized from WorldScenes by the
-- Lore registrar. Preserve that exact subject and its original discovery gate
-- when a numeric source binding needs it before registration.
local function existing(id)
 if byID[id]then return byID[id]end
 for _,c in pairs(ns.AthenaWorldScenes.figures)do if c.key==id then
  local e={id=id,title=c.title,kind='figure',category=id=='vancleef' and 'fallenpowers' or nil,
   sourceURL=c.sourceURL,fields={context=c.body},aliases=c.aliases or {c.title},variants=c.variants,
   gate=c.requiredQuestMention and 'QUEST_MENTION' or id=='vancleef' and 'DISCOVERY' or 'HISTORICAL',
   requiredMentions=c.requiredQuestMention and {'Arugal','worgen'} or nil}
  D.entries[#D.entries+1]=e;byID[id]=e;return e
 end end
end
for _,e in ipairs(model.newIdentitySubjects)do assert(not byID[e.id],'Duplicate encounter identity');D.entries[#D.entries+1]=e;byID[e.id]=e end
for _,r in ipairs(model.instances)do
 local e=assert(byID[r.id],'Missing source registry instance: '..r.id);assert(e.kind=='instance','Changed instance kind: '..r.id)
 e.encounterReferences=r.bosses;e.referenceLoot=r.referenceLoot;e.encounterReferenceQualification=r.qualification
 for _,b in ipairs(r.bosses)do local boss=assert(existing(b.loreID),'Missing existing boss registry subject: '..b.loreID);boss.related=boss.related or {};unique(boss.related,e.id)
  boss.encounterReferences=boss.encounterReferences or {};boss.encounterReferences[#boss.encounterReferences+1]={instanceID=e.id,
   sourceURL=b.sourceURL,sourceSHA256=b.sourceSHA256,publishedNPCID=b.publishedNPCID,entityType=b.entityType,
   optionalStatus='UNKNOWN',encounterOrderVerified=false,personalEncounterProven=false,currentForeverMechanicsVerified=false}
 end
end
for _,b in ipairs(model.canonicalNPCBindings)do
 local old,new=assert(byID[b.fromID]),assert(byID[b.toID]);assert(old.catalogReferenceOnly,'Cannot redirect authored unit identity')
 local ids={};for _,n in ipairs(old.npcIDs or {})do if n~=b.npcID then ids[#ids+1]=n end end;old.npcIDs=ids
 old.canonicalSubjectID=new.id;old.related=old.related or {};unique(old.related,new.id)
 new.npcIDs=new.npcIDs or {};unique(new.npcIDs,b.npcID)
end
